import React, { useEffect } from 'react';
import closeIcon from '@/assets/close.svg';
import styles from './CustomizationModal.module.css';
import { motion } from 'framer-motion';
import PropTypes from 'prop-types';
import { useAuthStore } from '@/store/authStore';
import { useRouter } from 'next/navigation';
import Image from 'next/image';
import { createPortal } from 'react-dom';
import { cloneRoadmap } from '@/service/roadmap.service';

// Animation variants
const animationVariants = {
  backdrop: {
    hidden: {
      opacity: 0,
      transition: { duration: 0.3 },
    },
    visible: {
      opacity: 1,
      transition: { duration: 0.2 },
    },
  },
  modal: {
    hidden: {
      y: 20,
      // scale: 0.8,
      opacity: 0,
      transition: {
        duration: 0.3,
        ease: 'easeInOut',
      },
    },
    visible: {
      y: 0,
      // scale: 1,
      opacity: 1,
      transition: {
        duration: 0.3,
        ease: 'easeOut',
      },
    },
    exit: {
      y: 40,
      transition: {
        duration: 0.3,
        ease: 'easeInOut',
      },
    },
  },
};

const CustomizationModal = ({ roadmap, setSelectedRoadmap }) => {
  const userDetails = useAuthStore((s) => s.userDetails);
  const router = useRouter();

  const handleCustomizeRoadmap = async (roadmap, cloneType) => {
    try {
      const response = await cloneRoadmap(
        roadmap?.title,
        roadmap?.description,
        roadmap?.id,
        cloneType,
      );

      const roadmapId = response?.id;
      router.push(`/draw-roadmap/${roadmapId}`);
    } catch (error) {
      console.log(error);
    }
  };

  const closeCustomizationModal = (event) => {
    event.stopPropagation();
    setSelectedRoadmap(null);
  };

  return (
    <motion.div
      className={styles['backdrop']}
      onClick={closeCustomizationModal}
      variants={animationVariants.backdrop}
      initial="hidden"
      animate="visible"
      exit="hidden"
      key="backdrop"
    >
      <motion.div
        className={styles['modal']}
        onClick={(e) => e.stopPropagation()}
        variants={animationVariants.modal}
        initial="hidden"
        animate="visible"
        exit="exit"
        key="modal"
      >
        <div className={styles['modal-head']}>
          <span className={styles['text']}>Choose the Option: </span>
          <button
            className={styles['close-btn']}
            onClick={closeCustomizationModal}
          >
            <Image src={closeIcon} alt="close" />
          </button>
        </div>

        <div className={styles['modal-body']}>
          <button
            className={styles['action-btn']}
            onClick={() => handleCustomizeRoadmap(roadmap, 'partial')}
          >
            <div className={styles['icon-ct']}>
              {/* <Image
                src={flowChartIcon}
                className={styles["flowchart-icon"]}
                alt=""
              />*/}
              <FlowChart className={styles['flowchart-icon']} />
            </div>
            <p className={styles['action-text']}>Clone Roadmap Diagram Only</p>
          </button>

          <button
            className={styles['action-btn']}
            onClick={() => handleCustomizeRoadmap(roadmap, 'all')}
          >
            <div className={styles['icon-ct']}>
              {/* <Image
                src={flowChartIcon}
                className={styles["flowchart-icon"]}
                alt=""
              />*/}
              <FlowChart className={styles['flowchart-icon']} />
              <PlusIcon />
              {/* <Image
                src={contentIcon}
                className={styles["content-icon"]}
                alt=""
              />*/}
              <Content className={styles['content-icon']} />
            </div>
            <p className={styles['action-text']}>Clone Roadmap with Content</p>
          </button>
        </div>
      </motion.div>
    </motion.div>
  );
};

